    /** QNN: a Snapdragon, but one Qualcomm publishes no Whisper assets for. */
    UNSUPPORTED_CHIPSET,

    /** Vulkan: the driver does not advertise the features whisper.cpp needs. */
    VULKAN_UNAVAILABLE,

    /**
