@Preview(showBackground = true)
@Composable
fun LanguagesScreen(navController: NavHostController = rememberNavController()) {
    val context = LocalContext.current
    val resources = LocalResources.current
    val deleteDialogInfo: MutableState<DeleteInfo?> = remember { mutableStateOf(null) }
    val languageDeleteInfo: MutableState<Locale?> = remember { mutableStateOf(null) }
    // Bumped whenever an import/delete may have changed which model is assigned,
    // so the per-language model names and backend options recompute.
    val gpuRevision = remember { mutableStateOf(0) }

    val inputMethods = useDataStoreValue(SubtypesSetting)
    val inputMethodList = remember(inputMethods) {
        Subtypes.layoutsMappedByLanguage(inputMethods)
    }

    val multilingualBucket = useDataStore(MultilingualBucketSetting)

    val inputMethodKeys = remember(inputMethodList) { inputMethodList.keys.toList().sorted() }

    if (deleteDialogInfo.value != null) {
        val info = deleteDialogInfo.value!!
        val dialogVoiceInputSelection = remember(info, gpuRevision.value) {
            ResourceHelper.resolveVoiceInputSelection(context, info.locale)
        }
        ConfirmResourceActionDialog(
            onDismissRequest = {
                gpuRevision.value++
                deleteDialogInfo.value = null
            },
            onExplore = {
                context.openURI(info.kind.getAddonUrlForLocale(info.locale), true)
                deleteDialogInfo.value = null
            },
            onDelete = {
                ResourceHelper.deleteResourceForLanguage(context, info.kind, info.locale)
                gpuRevision.value++
                deleteDialogInfo.value = null
            },
            onImport = {
                openModelImporter(context)
                gpuRevision.value++
                deleteDialogInfo.value = null
            },

            resourceKind = info.kind,
            locale = info.locale,
            isCurrentlySet = runBlocking {
                ResourceHelper.findFileForKind(
                    context,
                    info.locale,
                    info.kind
                )?.exists() == true
            },
            voiceInputBackends = remember(dialogVoiceInputSelection) {
                BackendSupport.availableBackends(
                    context,
                    dialogVoiceInputSelection.ggmlModel != null,
                    dialogVoiceInputSelection.qnnModel != null
                )
            },
            voiceInputBackend = dialogVoiceInputSelection.backend,
            voiceInputHasGgmlModel = dialogVoiceInputSelection.ggmlModel != null,
            voiceInputHasQnnModel = dialogVoiceInputSelection.qnnModel != null,
            voiceInputQnnUnavailable = if (dialogVoiceInputSelection.qnnModel != null) {
                BackendSupport.unavailableReason(
                    context,
                    Backend.QNN,
                    hasGgmlModel = dialogVoiceInputSelection.ggmlModel != null,
                    hasQnnModel = true
                )
            } else null,
            onVoiceInputBackendSelected = { backend ->
                ResourceHelper.setVoiceInputBackend(context, info.locale, backend)
                gpuRevision.value++
            }
        )
    } else if (languageDeleteInfo.value != null) {
        val info = languageDeleteInfo.value!!
        ConfirmDeleteLanguageDialog(
            locale = info,
            onDelete = {
                languageDeleteInfo.value = null

                val key = inputMethodKeys.find { localeString ->
                    Subtypes.getLocale(localeString) == info
                }

                if (key != null) {
                    val subtypes = inputMethodList[key]!!
                    subtypes.forEach { Subtypes.removeLanguage(context, it) }

                    if(multilingualBucket.value.contains(key)) {
                        multilingualBucket.value.toMutableSet().apply {
                            remove(key)
                            multilingualBucket.setValue(this)
                        }
                    }
                }
            },
            onDismissRequest = {
                languageDeleteInfo.value = null
            }
        )
    }
    LazyColumn(horizontalAlignment = Alignment.CenterHorizontally) {
        item {
            ScreenTitle(
                stringResource(R.string.language_settings_title),
                showBack = true,
                navController
            )
        }

        items(LanguageSettingsTop) {
            it.component()
        }

        items(inputMethodKeys) { localeString ->
            val subtypes = inputMethodList[localeString]!!

            val locale = Subtypes.getLocale(localeString)

            val name = Subtypes.getName(subtypes.first())

            // The same helper the voice input action uses, so the name shown
            // here is always the model that will actually run. That also makes
            // an assigned Qualcomm model visible (it used to show as "None").
            val voiceInputSelection = remember(gpuRevision.value, localeString) {
                ResourceHelper.resolveVoiceInputSelection(context, locale)
            }
            val voiceInputModelName = voiceInputSelection.model?.name?.let { stringResource(it) }
            val dictionaryName = runBlocking {
                ResourceHelper.findKeyForLocaleAndKind(
                    context,
                    locale,
                    FileKind.Dictionary
                )
            }?.let {
                runBlocking {
                    context.getSetting(
                        FileKind.Dictionary.namePreferenceKeyFor(it),
                        "Dictionary"
                    )
                } + " " + resources.getString(
                    R.string.language_settings_resource_imported_indicator
                )
             } ?: if (Dictionaries.getDictionaryIfExists(context, locale, Dictionaries.DictionaryKind.Any) != null) {
                resources.getString(R.string.language_settings_resource_builtin_dictionary_name)
            } else {
                null
            }

            val transformerName =
                runBlocking { ModelPaths.getModelOptions(context) }.get(locale.language)?.let {
                    it.loadDetails()?.let {
                        it.name + if (it.isUnsupported()) (" " + resources.getString(R.string.language_settings_resource_unsupported_indicator)) else ""
                    }
                }

            val voiceInputBackends = remember(voiceInputSelection) {
                BackendSupport.availableBackends(
                    context,

                            color = if (isSelected) MaterialTheme.colorScheme.primary
                            else MaterialTheme.colorScheme.outlineVariant,
                            shape = RoundedCornerShape(10.dp)
                        )
                        .clickable { onSelected(backend) },
                    contentAlignment = Alignment.Center
                ) {
                    Text(
                        text = stringResource(backend.displayNameRes()),
                        style = Typography.SmallMl,
                        color = if (isSelected) MaterialTheme.colorScheme.onPrimary
                        else MaterialTheme.colorScheme.onSurfaceVariant,
                        maxLines = 1
                    )
                }
            }
        }

        Text(
            stringResource(selected.descriptionRes()),
            modifier = Modifier.padding(start = 16.dp, end = 16.dp, top = 6.dp),
            style = Typography.Small,
            color = titleColor.copy(alpha = 0.75f)
        )

        if (unavailableReason != null) {
            Text(
                stringResource(unavailableMessageRes(selected, unavailableReason)),
                modifier = Modifier.padding(start = 16.dp, end = 16.dp, top = 4.dp),
                style = Typography.Small,
                color = MaterialTheme.colorScheme.error
            )
        }
    }
}

@Composable
fun ConfirmResourceActionDialog(
    onDismissRequest: () -> Unit,

    onExplore: () -> Unit,
    onDelete: () -> Unit,
    onImport: () -> Unit,

    resourceKind: FileKind,
    isCurrentlySet: Boolean,
    locale: Locale,
    voiceInputBackends: List<Backend> = emptyList(),
    voiceInputBackend: Backend = Backend.CPU,
    voiceInputHasGgmlModel: Boolean = false,
    voiceInputHasQnnModel: Boolean = false,
    voiceInputQnnUnavailable: BackendUnavailableReason? = null,
    onVoiceInputBackendSelected: (Backend) -> Unit = {}
) {
    val context = LocalContext.current
    val hasBuiltInFallback = if (resourceKind == FileKind.VoiceInput) {
        ResourceHelper.BuiltInVoiceInputFallbacks[locale.language] != null
    } else if (resourceKind == FileKind.VoiceInputQnn) {
        false
    } else if (resourceKind == FileKind.VoiceInputQnnZip) {
        false
    } else if (resourceKind == FileKind.Dictionary) {
        Dictionaries.getDictionaryIfExists(context, locale, Dictionaries.DictionaryKind.Any) != null
    } else {
        true
    }

    AlertDialog(
        icon = {
            Icon(painterResource(id = resourceKind.icon()), contentDescription = null)
        },
        title = {
            Text(text = "${locale.displayLanguage} - ${resourceKind.kindTitle(LocalResources.current)}")
        },
        text = {
            Column {
                if (isCurrentlySet) {
                    Text(
                        text = when (resourceKind) {
                            FileKind.VoiceInput -> stringResource(R.string.language_settings_resource_voice_input_selected)
                            FileKind.VoiceInputQnn -> stringResource(R.string.language_settings_resource_voice_input_qnn_selected)
                            FileKind.VoiceInputQnnZip -> stringResource(R.string.language_settings_resource_voice_input_qnn_selected)
                            FileKind.Transformer -> stringResource(R.string.language_settings_resource_transformer_selected)
                            FileKind.Dictionary -> stringResource(R.string.language_settings_resource_dictionary_selected)
                            FileKind.Invalid -> ""
                        } + if (!hasBuiltInFallback) {
                            "\n\n" +
                                    when (resourceKind) {
                                        FileKind.VoiceInput -> stringResource(R.string.language_settings_resource_voice_input_selected_no_default_warning)
                                        FileKind.VoiceInputQnn -> stringResource(R.string.language_settings_resource_voice_input_selected_no_default_warning)
                                        FileKind.VoiceInputQnnZip -> stringResource(R.string.language_settings_resource_voice_input_selected_no_default_warning)
                                        FileKind.Transformer -> stringResource(R.string.language_settings_resource_transformer_selected_no_default_warning)
                                        FileKind.Dictionary -> stringResource(R.string.language_settings_resource_dictionary_selected_no_default_warning)
                                        FileKind.Invalid -> ""
                                    }
                        } else {
                            ""
                        }
                    )
                } else {
                    Text(
                        text = when (resourceKind) {
                            FileKind.VoiceInput -> stringResource(R.string.language_settings_resource_voice_input_selected_unset)
                            FileKind.VoiceInputQnn -> stringResource(R.string.language_settings_resource_voice_input_selected_unset)
                            FileKind.VoiceInputQnnZip -> stringResource(R.string.language_settings_resource_voice_input_selected_unset)
                            FileKind.Transformer -> stringResource(R.string.language_settings_resource_transformer_selected_unset)
                            FileKind.Dictionary -> stringResource(R.string.language_settings_resource_dictionary_selected_unset)
                            FileKind.Invalid -> ""
                        }
                    )
                }

                // Voice-input kinds only: this dialog is shared with the
                // dictionary/transformer resources, where a transcription backend
                // is meaningless.
                val isVoiceInputKind = resourceKind == FileKind.VoiceInput ||
                        resourceKind == FileKind.VoiceInputQnn ||
                        resourceKind == FileKind.VoiceInputQnnZip
                if (isVoiceInputKind &&
                    (voiceInputBackends.size > 1 || voiceInputQnnUnavailable != null)
                ) {
                    Spacer(modifier = Modifier.height(16.dp))
                    VoiceInputBackendPicker(
                        backends = voiceInputBackends,
                        selected = voiceInputBackend,
                        hasGgmlModel = voiceInputHasGgmlModel,
                        hasQnnModel = voiceInputHasQnnModel,
                        onSelected = onVoiceInputBackendSelected
                    )
                    // Only when QNN is missing from the picker entirely: when it
                    // is offered, selecting it shows the same explanation.
                    if (voiceInputQnnUnavailable != null &&
                        Backend.QNN !in voiceInputBackends
                    ) {
                        Spacer(modifier = Modifier.height(6.dp))
                        Tip(
                            "⚠\uFE0F " + stringResource(
                                unavailableMessageRes(Backend.QNN, voiceInputQnnUnavailable)
                            )
                        )
                    }
                }
            }
        },
        onDismissRequest = {
            onDismissRequest()
        },
        confirmButton = {
            TextButton(onClick = {
                onImport()
            }) {
                Text(
                    if (isCurrentlySet) {
                        stringResource(R.string.language_settings_resource_replace_button)
                    } else {
                        stringResource(R.string.language_settings_resource_import_file_button)
                    }
                )
            }
        },
        dismissButton = {
            if (isCurrentlySet) {
                TextButton(onClick = { onDelete() }) {
                    if (hasBuiltInFallback) {
                        Text(stringResource(R.string.language_settings_resource_revert_to_default_button))
                    } else {
                        Text(stringResource(R.string.language_settings_resource_remove_button))
                    }

                }
            } else {
                TextButton(onClick = { onExplore() }) {
                    Text(stringResource(R.string.language_settings_resource_explore_online_button))
                }
            }
        }
    )
}


@Composable

// Whisper-on-HTP via ONNX Runtime's C API (the Java API lacks UINT16/UINT8
// tensor support). Runs Qualcomm AI Hub's precompiled QNN context binaries for
// Whisper-Large-V3-Turbo-Quantized (w8a16, qcs8550-proxy):
//   4 layers, 20 KV heads, 128-mel, uint16 activations / uint8 KV,
//   vocab 51866, <|nospeech|> = 50363, 100 language tokens (50259..50358)
//
// Fixed-shape KV-cache decode: 200-token window, right-aligned, one token per
// Run; self-KV outputs feed back verbatim (identical in/out quantization).
// Greedy = argmax over raw logits (affine quantization is monotonic).
// libonnxruntime.so is dlopen'd — no link-time dependency.
//
// Ported from whisper-htp-android (MIT):
//   https://github.com/thedevguy/whisper-htp-android

#include <android/log.h>
#include <dlfcn.h>
#include <jni.h>
#include <math.h>
#include <stdint.h>
#include <string.h>
#include <time.h>

#include <string>
#include <vector>
#include <atomic>

#include "onnxruntime_c_api.h"

#define TAG "QnnWhisper"
#define LOGI(...) __android_log_print(ANDROID_LOG_INFO, TAG, __VA_ARGS__)
#define LOGE(...) __android_log_print(ANDROID_LOG_ERROR, TAG, __VA_ARGS__)

// Mel front end (plain C++, see whisper_mel.cpp).
namespace mel {
bool init(const char* filtersPath, int nMel);
bool compute(const float* pcm, size_t nSamples, int nMel, int16_t* out);
int numMelBins();
}  // namespace mel

namespace {

constexpr int WINDOW = 200;  // decoder attention window (199 cache + current)
constexpr int CACHE = 199;
constexpr int HEAD_DIM = 64;
constexpr int MAX_LAYERS = 12;
constexpr int EOT = 50257;  // same in v2 and v3 vocabs; also the argmax cutoff
constexpr int LANG_FIRST = 50259;  // <|en|>; language tokens follow
constexpr int AUTO_DETECT_LANGUAGE = -1;  // prompt sentinel filled from <|sot|> logits

struct ModelCfg {
    int layers;
    int kvHeads;
    int melBins;
    bool fp16;  // false = w8a16 (uint16 activations / uint8 KV)
    int vocab;
    int noSpeechId;  // <|nospeech|>: 50362 in the v2 vocab, 50363 in v3
    int langCount;   // language tokens start at 50259: 99 in v2, 100 in v3
    float logitsScale;  // affine scale for w8a16 logits (unused for fp16)
};
constexpr ModelCfg CFG_SMALL = {12, 12, 80, false, 51865, 50362, 99, 0.0012925398768857121f};
constexpr ModelCfg CFG_TURBO = {4, 20, 128, true, 51866, 50363, 100, 0.0f};
constexpr ModelCfg CFG_TURBO_W8A16 = {4, 20, 128, false, 51866, 50363, 100, 0.0007861469639465213f};

// w8a16 affine params (metadata.json); fp16 variant needs none
constexpr uint16_t MASK_ATTEND_U16 = 65535;  // dequantizes to 0.0
constexpr uint16_t MASK_OFF_U16 = 0;         // dequantizes to -100.0
constexpr uint8_t KV_ZP_U8 = 128;

std::string g_lastError;

void setError(const std::string& msg) { g_lastError = msg; }

struct Handle {
    void* ortLib = nullptr;
    const OrtApi* api = nullptr;
    OrtEnv* env = nullptr;
    OrtSession* enc = nullptr;
    OrtSession* dec = nullptr;
    OrtMemoryInfo* mem = nullptr;
    ModelCfg cfg = CFG_TURBO_W8A16;
    OrtValue* cross[2 * MAX_LAYERS] = {};  // encoder outputs, constant per segment
    std::vector<uint8_t> selfKV[2 * MAX_LAYERS];
    int32_t inputId = 0;
    int32_t positionId = 0;
    uint16_t mask[WINDOW] = {};  // raw bits (uint16 or fp16 per variant)
    std::atomic<bool> cancelRequested{false};

    size_t kvElem() const { return cfg.fp16 ? 2 : 1; }
    size_t kvBytes() const { return (size_t)cfg.kvHeads * CACHE * HEAD_DIM * kvElem(); }
    ONNXTensorElementDataType kvType() const {
        return cfg.fp16 ? ONNX_TENSOR_ELEMENT_DATA_TYPE_FLOAT16 : ONNX_TENSOR_ELEMENT_DATA_TYPE_UINT8;
    }
    ONNXTensorElementDataType actType() const {  // mel, mask, logits
        return cfg.fp16 ? ONNX_TENSOR_ELEMENT_DATA_TYPE_FLOAT16 : ONNX_TENSOR_ELEMENT_DATA_TYPE_UINT16;
    }
};

uint16_t fp16Bits(float f) {
    __fp16 h = (__fp16)f;
    uint16_t b;
    memcpy(&b, &h, 2);
    return b;
}

float fromFp16(uint16_t b) {
    __fp16 h;
    memcpy(&h, &b, 2);
    return (float)h;
}

bool check(const OrtApi* api, OrtStatus* st, const char* what) {
    if (!st) return true;
    const char* msg = api->GetErrorMessage(st);
    LOGE("%s failed: %s", what, msg);
    setError(std::string(what) + ": " + msg);
    api->ReleaseStatus(st);
    return false;
}

OrtSession* createQnnSession(Handle* h, const char* modelPath, const std::string& libDir) {
    const OrtApi* api = h->api;
    OrtSessionOptions* opts = nullptr;
    if (!check(api, api->CreateSessionOptions(&opts), "CreateSessionOptions")) return nullptr;
    api->SetSessionGraphOptimizationLevel(opts, ORT_DISABLE_ALL);
    std::string backend = libDir + "/libQnnHtp.so";
    // high_performance (NOT burst): burst drove the passively-cooled reference
    // device to thermal-emergency; high_performance keeps most of the speed at
    // sustainable clocks.
    const char* keys[] = {"backend_path", "htp_performance_mode"};
    const char* vals[] = {backend.c_str(), "high_performance"};
    if (!check(api, api->SessionOptionsAppendExecutionProvider(opts, "QNN", keys, vals, 2),
               "AppendExecutionProvider(QNN)")) {
        api->ReleaseSessionOptions(opts);
        return nullptr;
    }
    OrtSession* session = nullptr;
    bool ok = check(api, api->CreateSession(h->env, modelPath, opts, &session), modelPath);
    api->ReleaseSessionOptions(opts);
    return ok ? session : nullptr;
}

void resetSelfKV(Handle* h) {
    for (int i = 0; i < 2 * h->cfg.layers; i++) {
        h->selfKV[i].assign(h->kvBytes(), h->cfg.fp16 ? 0 : KV_ZP_U8);
    }
}

// The encoder output cross-attention caches are per-segment state. The engine
// reuses one handle for several segments (long-form chunking in
// QnnWhisperEngine.infer), and the next encoder Run overwrites h->cross without
// freeing what was there, so drop them once the decoder is done with them.
void releaseCross(Handle* h) {
    for (auto*& v : h->cross) {
        if (v) {
            h->api->ReleaseValue(v);
            v = nullptr;
        }
    }
}

void destroy(Handle* h) {
    if (!h) return;
    if (h->api) {
        releaseCross(h);
        if (h->mem) h->api->ReleaseMemoryInfo(h->mem);
        if (h->enc) h->api->ReleaseSession(h->enc);
        if (h->dec) h->api->ReleaseSession(h->dec);
        if (h->env) h->api->ReleaseEnv(h->env);
    }
    if (h->ortLib) dlclose(h->ortLib);
    delete h;
}

}  // namespace

// ---------------------------------------------------------------- JNI

extern "C" {

static jlong nativeInit(JNIEnv* env, jobject, jstring jLibDir, jstring jEncPath,
                        jstring jDecPath, jint variant) {
    g_lastError.clear();
    const char* c;
    c = env->GetStringUTFChars(jLibDir, nullptr);  std::string libDir = c;  env->ReleaseStringUTFChars(jLibDir, c);
    c = env->GetStringUTFChars(jEncPath, nullptr); std::string encPath = c; env->ReleaseStringUTFChars(jEncPath, c);
    c = env->GetStringUTFChars(jDecPath, nullptr); std::string decPath = c; env->ReleaseStringUTFChars(jDecPath, c);

    auto* h = new Handle();
    switch (variant) {
        case 0: h->cfg = CFG_SMALL; break;
        case 1: h->cfg = CFG_TURBO; break;
        default: h->cfg = CFG_TURBO_W8A16; break;
    }
    std::string ortPath = libDir + "/libonnxruntime.so";
    h->ortLib = dlopen(ortPath.c_str(), RTLD_NOW | RTLD_LOCAL);
    if (!h->ortLib) {
        LOGE("dlopen(%s): %s", ortPath.c_str(), dlerror());
        setError(std::string("dlopen libonnxruntime.so: ") + dlerror());
        destroy(h);
        return 0;
    }
    auto getApiBase = reinterpret_cast<const OrtApiBase* (*)()>(dlsym(h->ortLib, "OrtGetApiBase"));
    if (!getApiBase) {
        LOGE("dlsym OrtGetApiBase: %s", dlerror());
        setError("dlsym OrtGetApiBase failed");
        destroy(h);
        return 0;
    }
    h->api = getApiBase()->GetApi(ORT_API_VERSION);
    if (!h->api) {
        LOGE("GetApi(%d) returned null (runtime older than header?)", ORT_API_VERSION);
        setError("ORT API version mismatch");
        destroy(h);
        return 0;
    }
    const OrtApi* api = h->api;
    if (!check(api, api->CreateEnv(ORT_LOGGING_LEVEL_WARNING, "QnnWhisper", &h->env), "CreateEnv") ||
        !check(api, api->CreateCpuMemoryInfo(OrtArenaAllocator, OrtMemTypeDefault, &h->mem),
               "CreateCpuMemoryInfo")) {
        destroy(h);
        return 0;
    }

    h->enc = createQnnSession(h, encPath.c_str(), libDir);
    if (!h->enc) { destroy(h); return 0; }
    h->dec = createQnnSession(h, decPath.c_str(), libDir);
    if (!h->dec) { destroy(h); return 0; }
    LOGI("sessions created (variant=%d: %d layers, %d kv-heads, %d mel bins, %s)", variant,
         h->cfg.layers, h->cfg.kvHeads, h->cfg.melBins, h->cfg.fp16 ? "fp16" : "w8a16");

    resetSelfKV(h);
    return reinterpret_cast<jlong>(h);
}

static void nativeFree(JNIEnv*, jobject, jlong jh) {
    destroy(reinterpret_cast<Handle*>(jh));
}

static void nativeCancel(JNIEnv*, jobject, jlong jh) {
    auto* h = reinterpret_cast<Handle*>(jh);
    if (h) h->cancelRequested.store(true);
}

static jstring nativeLastError(JNIEnv* env, jobject) {
    return env->NewStringUTF(g_lastError.c_str());

