private fun logAndDumpInput(samples: FloatArray) {
    var sumSquares = 0.0
    var peak = 0f
    for (sample in samples) {
        sumSquares += sample.toDouble() * sample
        peak = max(peak, abs(sample))
    }
    val rms = if (samples.isEmpty()) 0.0 else sqrt(sumSquares / samples.size)
    Log.i("VoiceInputSelect", "QnnWhisperEngine input samples=${samples.size} rms=$rms peak=$peak")

    // Temporary diagnostic: keep the exact PCM handed to the HTP model so a
    // failed transcription can be replayed with a reference implementation.
    try {
        val dir = appContext.getExternalFilesDir(null) ?: return
        val pcm = ByteArray(minOf(samples.size, 16000 * 300) * 2)
        for (i in 0 until pcm.size / 2) {
            val v = (samples[i].coerceIn(-1f, 1f) * 32767f).toInt()
            pcm[2 * i] = (v and 0xFF).toByte()
            pcm[2 * i + 1] = ((v shr 8) and 0xFF).toByte()
        }
        FileOutputStream(File(dir, "qnn-last-input.wav")).use { out ->
            fun le32(value: Int) {
                out.write(value and 0xFF)
                out.write((value shr 8) and 0xFF)
                out.write((value shr 16) and 0xFF)
                out.write((value shr 24) and 0xFF)
            }
            fun le16(value: Int) {
                out.write(value and 0xFF)
                out.write((value shr 8) and 0xFF)
            }
            out.write("RIFF".toByteArray())
            le32(36 + pcm.size)
            out.write("WAVE".toByteArray())
            out.write("fmt ".toByteArray())
            le32(16)
            le16(1)          // PCM
            le16(1)          // mono
            le32(16000)      // sample rate
            le32(32000)      // byte rate
            le16(2)          // block align
            le16(16)         // bits per sample
            out.write("data".toByteArray())
            le32(pcm.size)
            out.write(pcm)
        }
    } catch (e: Throwable) {
        Log.w("VoiceInputSelect", "QnnWhisperEngine PCM dump failed", e)
    }
}

