private fun preserveDump(prefix: String, languages: Array<String>, chunkStart: Int) {
    try {
        val dir = appContext.getExternalFilesDir(null) ?: return
        val source = File(dir, "qnn-last-input.wav")
        if (!source.exists()) return
        val lang = languages.joinToString("-").ifEmpty { "auto" }
        source.copyTo(
            File(dir, "qnn-$prefix-$lang-$chunkStart-${System.currentTimeMillis()}.wav"),
            overwrite = true
        )
        // Temporary diagnostic: keep a bounded history of recent attempts.
        val dumps = dir.listFiles { f ->
            f.name.startsWith("qnn-") && f.name != "qnn-last-input.wav" && f.name.endsWith(".wav")
        }?.sortedBy { it.lastModified() } ?: return
        dumps.dropLast(20).forEach { it.delete() }
    } catch (e: Throwable) {
        Log.w("VoiceInputSelect", "QnnWhisperEngine preserve dump failed", e)
    }
}

